#!/usr/bin/env python3
"""Arm A0r: the original seed user turns with the assistant turns regenerated by each conversation's released
responder, with no persona, through the pipeline's continuity loop and sanity gate (regen.py).

  build   <work>/a0r/input/NNN.jsonl from <work>/data/A0_source.jsonl (build_arms.py) and the release (responder,
          persona id); CPU, seconds
  run     regenerate the given input shards into <work>/a0r/out/<shard>; needs the Gemma, Ministral and MiniMax-M2.5
          endpoints; resumable by id. Shard groups can run as separate jobs (--shards).

  python -m personafactory.downstream.a0r build --work $PF_OUT_DIR/downstream --release swiss-ai/PersonaFactory
  python -m personafactory.downstream.a0r run --work $PF_OUT_DIR/downstream \
      --gemma $GEMMA_URL --ministral $MINISTRAL_URL --minimax $MINIMAX_URL --concurrency 160
"""
import argparse, asyncio, hashlib, json, os

from personafactory.downstream.common import HF_REPO, load_release


def build(work, release, nshards):
    src = {}
    for line in open(os.path.join(work, 'data', 'A0_source.jsonl'), encoding='utf-8'):
        r = json.loads(line)
        src[r['id']] = r
    meta = {r['id']: (r['persona_id'], r['responder']) for r in load_release(release) if r['id'] in src}
    d = os.path.join(work, 'a0r', 'input')
    os.makedirs(d, exist_ok=True)
    fhs = [open(os.path.join(d, f'{i:03d}.jsonl'), 'w', encoding='utf-8') for i in range(nshards)]
    for k, r in sorted(src.items()):
        pid, resp = meta[k]
        users = [m['content'] for m in r['messages'] if m['role'] == 'user']
        fhs[int(hashlib.md5(k.encode()).hexdigest(), 16) % nshards].write(json.dumps({
            'id': k, 'persona_id': pid, 'responder': resp,
            'fixed': [{'user_message': u, 'user_message_original': u, 'persona_applied': False} for u in users]},
            ensure_ascii=False) + '\n')
    for f in fhs:
        f.close()
    print('built', len(src), 'records in', nshards, 'shards')


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument('step', choices=['build', 'run'])
    ap.add_argument('--work', default=os.path.join(os.environ.get('PF_OUT_DIR', './outputs'), 'downstream'))
    ap.add_argument('--release', default=HF_REPO)
    ap.add_argument('--nshards', type=int, default=32)
    a, rest = ap.parse_known_args()
    if a.step == 'build':
        build(a.work, a.release, a.nshards)
        return
    from personafactory.downstream import regen
    rp = argparse.ArgumentParser()
    regen.add_args(rp)
    r = rp.parse_args(rest)
    asyncio.run(regen.run(r, os.path.join(a.work, 'a0r', 'input'), os.path.join(a.work, 'a0r', 'out'), translate=False))


if __name__ == '__main__':
    main()
